  "faq_1_a": "হ্যাঁ, অবশ্যই। CCTVQuotation-এর প্রতিটি কোটেশনে 18% GST আগে থেকেই ধরা থাকে — কোনো লুকানো চার্জ নেই। এতে ক্যামেরা, DVR/NVR, কেবল এবং সম্পূর্ণ ফিটিং সবই ধরা থাকে।",
